<?php namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Builder;class UpbringingTask extends Model{protected $table='upbringing_tasks';protected $guarded=[];protected static function booted():void{static::addGlobalScope('period',function(Builder $q){$p=request()->attributes->get('academic_period');if($p)$q->where('academic_period_id',$p->id);});}}